```javascript
import {
  Group,
  Mesh,
  PlaneGeometry,
  BoxGeometry,
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
  Color,
  Vector2,
  Vector3,
  DoubleSide
} from 'three/webgpu';
import {
  uniform,
  texture,
  uv,
  positionLocal,
  vec2,
  vec3,
  vec4,
  float,
  mix,
  Fn
} from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const COLORS = {
    ink: new Color('#16161d'),
    paper: new Color('#e8ecf2'),
    accent: new Color('#ff2a38'),
    surface: new Color('#0b0b10')
  };

  const group = new Group();
  group.position.set(-1.25, 1.6, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);
  group.name = 'hub-features-row';

  // --- Textures (cached, synchronous) ---
  const colorMap = ctx.textureLoader('/prism-mock/home/nodes/parallax-stack.png');
  const depthMap = ctx.textureLoader('/prism-mock/home/nodes/parallax-stack.depth.png');

  // atlas region 0,0,512,320 — assume full texture; build uv transform uniforms
  const uvScale = uniform(new Vector2(1, 1));
  const uvOffset = uniform(new Vector2(0, 0));

  // --- Parallax plane ---
  const PLANE_W = 2.5;
  const PLANE_H = 0.55;
  const geo = new PlaneGeometry(PLANE_W, PLANE_H, 64, 64);

  const dispIntensity = uniform(0.05);
  const parallaxStrength = uniform(0.04);
  const cursorOffset = uniform(new Vector2(0, 0));

  const material = new MeshStandardNodeMaterial();
  material.side = DoubleSide;
  material.metalness = 0.55;
  material.roughness = 0.5;
  material.clearcoat = 0.25;

  // TSL displacement + parallax sampling
  const atlasUV = uv().mul(uvScale).add(uvOffset);
  const depthVal = texture(depthMap, atlasUV).r;
  const parallaxShift = cursorOffset.mul(depthVal.sub(float(0.5))).mul(parallaxStrength);
  const sampleUV = atlasUV.sub(parallaxShift);

  material.colorNode = texture(colorMap, sampleUV);
  material.positionNode = positionLocal.add(
    vec3(float(0.0), float(0.0), depthVal.sub(float(0.5)).mul(dispIntensity))
  );

  const plane = new Mesh(geo, material);
  plane.position.set(0, 0, 0);
  group.add(plane);

  // --- Divider (subtle line) ---
  const dividerGeo = new BoxGeometry(2.4, 0.006, 0.004);
  const dividerMat = new MeshBasicNodeMaterial();
  dividerMat.colorNode = mix(vec4(COLORS.ink, 1.0), vec4(COLORS.accent, 1.0), float(0.0));
  // we'll animate the mix via a uniform
  const dividerMix = uniform(0.0);
  dividerMat.colorNode = mix(
    vec4(vec3(COLORS.ink), float(1.0)),
    vec4(vec3(COLORS.accent), float(1.0)),
    dividerMix
  );
  dividerMat.transparent = true;
  const divider = new Mesh(dividerGeo, dividerMat);
  divider.position.set(0, -PLANE_H / 2 + 0.02, 0.001);
  group.add(divider);

  // --- Accent edge (left vertical line, appears on focus/hover) ---
  const edgeGeo = new BoxGeometry(0.012, PLANE_H * 0.7, 0.004);
  const edgeMat = new MeshBasicNodeMaterial();
  const edgeOpacity = uniform(0.0);
  edgeMat.colorNode = vec4(vec3(COLORS.accent), edgeOpacity);
  edgeMat.transparent = true;
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.set(-PLANE_W / 2 + 0.02, 0, 0.002);
  group.add(edge);

  // --- Title + meta text via font atlas ---
  // (textContent is none; use sensible Features-row defaults)
  const titleMesh = ctx.fontAtlas.createText({
    text: 'Precision Movement',
    family: 'Lora',
    weight: 600,
    size: 0.2,
    color: COLORS.paper,
    align: 'left'
  });
  titleMesh.position.set(-PLANE_W / 2 + 0.18, 0.06, 0.004);
  group.add(titleMesh);

  const metaMesh = ctx.fontAtlas.createText({
    text: 'MECHANICAL · 72H RESERVE',
    family: 'JetBrains Mono',
    weight: 400,
    size: 0.09,
    color: COLORS.paper.clone().multiplyScalar(0.6),
    align: 'left'
  });
  metaMesh.position.set(-PLANE_W / 2 + 0.18, -0.12, 0.004);
  group.add(metaMesh);

  // right-side meta (index / count)
  const indexMesh = ctx.fontAtlas.createText({
    text: '01 / 06',
    family: 'JetBrains Mono',
    weight: 700,
    size: 0.09,
    color: COLORS.accent,
    align: 'right'
  });
  indexMesh.position.set(PLANE_W / 2 - 0.18, 0.06, 0.004);
  group.add(indexMesh);

  // --- Interaction state ---
  const state = {
    hovered: false,
    focused: false,
    liftY: 0,
    pressScale: 1,
    timelines: []
  };

  const killTimelines = () => {
    state.timelines.forEach((t) => t.kill());
    state.timelines = [];
  };

  const addTimeline = (tl) => {
    state.timelines.push(tl);
    return tl;
  };

  // hover lift (rise-in subtle 0.15)
  const onPointerEnter = () => {
    state.hovered = true;
    killTimelines();
    const tl = gsap.timeline();
    tl.to(group.position, { y: 1.6 + 0.15, duration: 0.7, ease: 'power3.out' }, 0);
    tl.to(dividerMix, { value: 1.0, duration: 0.5, ease: 'power2.out' }, 0);
    tl.to(edgeOpacity, { value: 1.0, duration: 0.4, ease: 'power2.out' }, 0);
    addTimeline(tl);
  };

  const onPointerLeave = () => {
    state.hovered = false;
    if (state.focused) return; // keep accent edge if focused
    killTimelines();
    const tl = gsap.timeline();
    tl.to(group.position, { y: 1.6, duration: 0.6, ease: 'power3.out' }, 0);
    tl.to(dividerMix, { value: state.focused ? 1.0 : 0.0, duration: 0.5, ease: 'power2.out' }, 0);
    tl.to(edgeOpacity, { value: state.focused ? 1.0 : 0.0, duration: 0.4, ease: 'power2.out' }, 0);
    addTimeline(tl);
  };

  // press-down on click
  const onClick = () => {
    killTimelines();
    const tl = gsap.timeline();
    tl.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
    tl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.18, ease: 'back.out(2)' });
    addTimeline(tl);
    // emit event with bound navigate payload
    if (config.onEvent) {
      config.onEvent({
        type: 'hub-features.select',
        target: 'hub-features',
        binding: { source: 'trpc.checkout.begin.checkoutUrl', target: 'onClick.navigate' }
      });
    }
  };

  const onFocus = () => {
    state.focused = true;
    killTimelines();
    const tl = gsap.timeline();
    tl.to(edgeOpacity, { value: 1.0, duration: 0.3, ease: 'power2.out' }, 0);
    tl.to(dividerMix, { value: 1.0, duration: 0.3, ease: 'power2.out' }, 0);
    addTimeline(tl);
  };

  const onBlur = () => {
    state.focused = false;
    killTimelines();
    const tl = gsap.timeline();
    tl.to(edgeOpacity, { value: state.hovered ? 1.0 : 0.0, duration: 0.3, ease: 'power2.out' }, 0);
    tl.to(dividerMix, { value: state.hovered ? 1.0 : 0.0, duration: 0.3, ease: 'power2.out' }, 0);
    addTimeline(tl);
  };

  // parallax cursor tracking — apply parallax-scroll primitive (render mode requires it)
  // config.cinematicPrimitives is empty, but render mode guidance mandates parallax.
  if (ctx.primitives && ctx.primitives['parallax-scroll']) {
    ctx.primitives['parallax-scroll'](plane, {
      depthMap,
      cursorOffset,
      parallaxStrength,
      intensity: 0.04
    });
  }

  // also expose a pointermove handler to feed cursorOffset
  const onPointerMove = (e) => {
    // e.point is world coords on the plane; map to [-1,1] cursor offset
    if (!e || !e.point) return;
    const local = group.worldToLocal(e.point.clone());
    const nx = (local.x / PLANE_W) * 2.0;
    const ny = (local.y / PLANE_H) * 2.0;
    cursorOffset.value.set(
      gsap.utils.clamp(-1, 1, nx),
      gsap.utils.clamp(-1, 1, ny)
    );
  };

  group.userData.handlers = {
    pointerenter: onPointerEnter,
    pointerleave: onPointerLeave,
    click: onClick,
    focus: onFocus,
    blur: onBlur,
    pointermove: onPointerMove
  };

  group.userData.cleanup = () => {
    killTimelines();
    geo.dispose();
    material.dispose();
    dividerGeo.dispose();
    dividerMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    [titleMesh, metaMesh, indexMesh].forEach((m) => {
      if (m && typeof m.dispose === 'function') m.dispose();
      if (m && m.geometry) m.geometry.dispose && m.geometry.dispose();
      if (m && m.material) m.material.dispose && m.material.dispose();
    });
  };

  return group;
}
